    sha: "e3ab9108a809fb834f73df4b1c44da3bbdc89409",
    short: "e3ab910",
    subject: "ci(release): enable reviewed one-shot candidate branch trigger (#76)",
    author: "Gabriele Lucia",
    date: "2026-11-15T11:24:09+01:00",
    kind: "ci",
    body: "Allow creation of a fresh release-candidate/vX.Y.Z-rc.N ref pointing exactly at green current main to invoke the existing secure release preparation and artifact attestation pipeline; preserve manual workflow dispatch. PR CI and CodeQL/security all passed.",
    files: [{"path":".github/workflows/prepare-rc.yml","added":35,"deleted":13,"binary":false,"patch":"diff --git a/.github/workflows/prepare-rc.yml b/.github/workflows/prepare-rc.yml\nindex 81640b2..3a25856 100644\n--- a/.github/workflows/prepare-rc.yml\n+++ b/.github/workflows/prepare-rc.yml\n@@ -1,6 +1,9 @@\n name: Prepare first YAG release candidate\n \n on:\n+  # A newly created dedicated candidate branch triggers the trusted\n+  # default-branch workflow; no unreviewed source is checked out.\n+  create:\n   workflow_dispatch:\n     inputs:\n       tag:\n@@ -19,25 +22,48 @@ concurrency:\n jobs:\n   prepare:\n     name: Verify main and create a new candidate tag\n-    if: github.ref == 'refs/heads/main'\n+    if: >-\n+      (github.event_name == 'workflow_dispatch' && github.ref == 'refs/heads/main') ||\n+      (github.event_name == 'create' && github.event.ref_type == 'branch' && startsWith(github.event.ref, 'release-candidate/'))\n     runs-on: ubuntu-24.04\n     timeout-minutes: 12\n     environment: release-candidate\n     steps:\n       - uses: actions/checkout@v4\n         with:\n+          ref: main\n           persist-credentials: false\n-      - name: Confirm this workflow still points at current main\n+      - name: Verify a newly created candidate branch or explicitly dispatched main\n         shell: bash\n         env:\n           GH_TOKEN: ${{ github.token }}\n+          CREATED_REF: ${{ github.event.ref }}\n+          CREATED_REF_TYPE: ${{ github.event.ref_type }}\n+          INPUT_TAG: ${{ inputs.tag }}\n         run: |\n           set -euo pipefail\n           current=\"$(gh api \"repos/$GITHUB_REPOSITORY/git/ref/heads/main\" --jq '.object.sha')\"\n-          if [[ \"$current\" != \"$GITHUB_SHA\" ]]; then\n-            echo \"Main moved; re-run this review on the latest commit.\" >&2\n-            exit 1\n+          if [[ \"$GITHUB_EVENT_NAME\" == create ]]; then\n+            if [[ \"$CREATED_REF_TYPE\" != branch ||\n+                  ! \"$CREATED_REF\" =~ ^release-candidate/v[0-9]+\\.[0-9]+\\.[0-9]+-rc\\.[1-9][0-9]*$ ]]; then\n+              echo \"Only an exact release-candidate/vMAJOR.MINOR.PATCH-rc.N branch may trigger a candidate.\" >&2\n+              exit 1\n+            fi\n+            candidate_commit=\"$(gh api \"repos/$GITHUB_REPOSITORY/git/ref/heads/$CREATED_REF\" --jq '.object.sha')\"\n+            if [[ \"$candidate_commit\" != \"$current\" ]]; then\n+              echo \"Candidate trigger must point to the current reviewed main commit.\" >&2\n+              exit 1\n+            fi\n+            tag=\"${CREATED_REF#release-candidate/}\"\n+          else\n+            if [[ \"$GITHUB_REF\" != refs/heads/main || \"$current\" != \"$GITHUB_SHA\" ]]; then\n+              echo \"Main moved; re-run this review on the latest commit.\" >&2\n+              exit 1\n+            fi\n+            tag=\"$INPUT_TAG\"\n           fi\n+          # The Python policy validates the exact release tag again.\n+          printf 'RC_TAG=%s\\nREVIEWED_SHA=%s\\n' \"$tag\" \"$current\" >> \"$GITHUB_ENV\"\n       - name: Download exact main-commit CI/security run metadata\n         shell: bash\n         env:\n@@ -45,23 +71,20 @@ jobs:\n         run: |\n           set -euo pipefail\n           umask 077\n-          gh api \"repos/$GITHUB_REPOSITORY/actions/runs?head_sha=$GITHUB_SHA&per_page=100\" \\\n+          gh api \"repos/$GITHUB_REPOSITORY/actions/runs?head_sha=$REVIEWED_SHA&per_page=100\" \\\n             > \"$RUNNER_TEMP/yag-candidate-runs.json\"\n       - name: Fail closed unless newest CI and security reviews passed\n         shell: bash\n-        env:\n-          RC_TAG: ${{ inputs.tag }}\n         run: |\n           set -euo pipefail\n           python3 scripts/release_candidate.py \\\n-            --tag \"$RC_TAG\" --commit \"$GITHUB_SHA\" \\\n+            --tag \"$RC_TAG\" --commit \"$REVIEWED_SHA\" \\\n             --repository \"$GITHUB_REPOSITORY\" \\\n             --runs-file \"$RUNNER_TEMP/yag-candidate-runs.json\"\n       - name: Create immutable lightweight prerelease tag\n         shell: bash\n         env:\n           GH_TOKEN: ${{ github.token }}\n-          RC_TAG: ${{ inputs.tag }}\n         run: |\n           set -euo pipefail\n           # Never force, replace or re-sign an existing release tag.\n@@ -70,12 +93,11 @@ jobs:\n             exit 1\n           fi\n           gh api -X POST \"repos/$GITHUB_REPOSITORY/git/refs\" \\\n-            -f ref=\"refs/tags/$RC_TAG\" -f sha=\"$GITHUB_SHA\" >/dev/null\n+            -f ref=\"refs/tags/$RC_TAG\" -f sha=\"$REVIEWED_SHA\" >/dev/null\n       - name: Explicitly dispatch the packaged prerelease workflow\n         shell: bash\n         env:\n           GH_TOKEN: ${{ github.token }}\n-          RC_TAG: ${{ inputs.tag }}\n         run: |\n           set -euo pipefail\n           # GITHUB_TOKEN tag pushes intentionally do not trigger normal push\n@@ -84,7 +106,7 @@ jobs:\n           {\n             echo \"### Release candidate prepared\"\n             echo \"Tag: \\`$RC_TAG\\`\"\n-            echo \"Commit: \\`$GITHUB_SHA\\`\"\n+            echo \"Commit: \\`$REVIEWED_SHA\\`\"\n             echo \"Packaging, checksum and Sigstore attestation run in the release workflow.\"\n             echo \"Only prerelease publication is authorized. No production certification.\"\n           } >> \"$GITHUB_STEP_SUMMARY\"\n","truncated":false},{"path":"docs/deployment/releases.md","added":16,"deleted":0,"binary":false,"patch":"diff --git a/docs/deployment/releases.md b/docs/deployment/releases.md\nindex a54ddde..339f64b 100644\n--- a/docs/deployment/releases.md\n+++ b/docs/deployment/releases.md\n@@ -26,6 +26,22 @@ packaging workflow. No GitHub prerelease is claimed until all builds,\n checksums and signed provenance pass. See\n [first release requirements](../operations/first-release.md).\n \n+### Start an RC without an Actions dispatch API\n+\n+An alternative one-shot trigger is to create the exact branch\n+`release-candidate/v0.1.0-rc.1` **from the latest reviewed main**.\n+GitHub's `create` event runs the default-branch preparatory workflow.\n+The workflow checks that the candidate branch still points to current\n+`main`, verifies the latest exact-commit CI and security results, rejects\n+existing tags, creates the immutable `v0.1.0-rc.1` tag, then explicitly\n+dispatches release packaging. Never force-move a release candidate branch\n+or reuse a tag. This path has the same prerelease checks as the manual\n+`workflow_dispatch`; it does **not** approve stable publication.\n+\n+A source-branch creation is only an *attempt*. Check the resulting Actions\n+logs and GitHub Releases page; a tag or published prerelease must never be\n+claimed solely because the branch exists.\n+\n ## Release candidates versus stable publication\n \n For the first public release, use a reviewed prerelease tag such as\n","truncated":false}],
